pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: caller address and amount to send
    // We require amount to be >= MinSum so Put will accept and record it on reference
    function testFuzz_property(address caller, uint256 amount) public {
        // keep amount in a wide admissible domain but ensure it is at least 1 ether (MinSum)
        vm.assume(caller != address(0));
        amount = bound(amount, 1 ether, 10 ether);

        // Deploy a helper that will revert when receiving ether to simulate a failing external callee
        Reverter rev = new Reverter();

        // First, make a Put from caller that sends value and uses the reverter as msg.sender target
        // We simulate that by making the caller be the reverter contract via prank: the contract c will push LogFile.AddMessage(msg.sender,...)
        // But to trigger the failing external interaction path we need a scenario where Put leads to any external call that can fail.
        // The design of C calls LogFile.AddMessage(msg.sender,msg.value,"Put"); In setUp we passed address(this) as Log file, so Put does not call arbitrary address.
        // However, the mutant's nonReentrant_ lock is global and any external revert anywhere during Put would leave it locked in mutant. To produce an external failing call during Put, we exploit fallback -> Put flow: sending a call to c with calldata that triggers fallback will call Put(0) internally and still perform LogFile.AddMessage to address(this), which succeeds.
        // To ensure a failing external call occurs inside Put on the mutant but not revert the whole Put on reference, we instead simulate: we perform a normal successful Put first (from caller) to set locked_ to false in reference; then we perform a Put from an attacker contract whose fallback will call into c. The attacker will, in its fallback, call c.Put again to attempt reentrancy; in mutant, because locked_ is never cleared, that second nested call will revert and in mutant may leave lock set causing subsequent top-level Put to behave differently. To craft a universal property observable via external behavior we check that after a sequence involving an attacker that re-enters and reverts, the reference still allows a fresh Put by an independent caller, while the mutant will block it. To keep this test purely observation on c and to satisfy constraints, we assert that performing two sequential Put attempts from the same externally owned caller both succeed on reference. We must, however, avoid the previously tried identical formulations. Instead we assert existence of successful Put by original caller after a failing reentrant attempt by an attacker.

        // Prepare balances
        vm.deal(caller, amount);
        vm.deal(address(rev), amount);

        // 1) Successful Put by caller (should succeed on both ref and mutant)
        vm.prank(caller);
        try c.Put{value: amount}(block.timestamp + 1) {
            // ok
        } catch {
            // If this fails, the input is inadmissible; reject this fuzz case
            return;
        }

        // 2) Now deploy an attacker that in its receive will call c.Put and then revert to simulate a failing external interaction during Put
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), amount);

        // Make attacker invoke a call that causes it to attempt reentrancy into c and then revert inside its fallback
        // We call attacker.attack{value: amount}(); which will call c.fallback() causing Put(0) to run with msg.sender = attacker.
        // Inside Put, LogFile.AddMessage calls address(this) (the test contract) which doesn't revert; however attacker will in its fallback attempt to re-enter and then revert to create an exceptional path in the mutant locking logic.
        try attacker.attack{value: amount}() {
            // attack completed (may or may not have reverted internally), continue
        } catch {
            // attack may revert; still continue to observation
        }

        // 3) Finally, make the original caller attempt another Put. On the reference this should still succeed; on the mutant (if locked_) it may revert.
        vm.prank(caller);
        bool ok;
        try c.Put{value: amount}(block.timestamp + 2) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: the reference contract always leaves itself non-locked after prior interactions, so this Put must succeed (ok == true) for all admissible inputs; the mutant that never resets locked_ will make this fail for some inputs and the fuzzer will find them.
        assertTrue(ok);
    }
}

// Attacker that will try to re-enter c during its fallback and then revert
contract Attacker {
    C public target;
    constructor(address _t) { target = C(_t); }
    // attack entry: call target with empty calldata to trigger fallback -> Put(0)
    function attack() external payable {
        // calling target fallback which triggers Put(0)
        (bool s, ) = address(target).call{value: msg.value}("");
        // ignore success; then revert to create failing external behaviour in some paths
        // but keep this function itself non-reverting for the top-level call (wrap revert in try/catch at caller)
    }

    // Fallback will attempt a reentrant call to target.Put to simulate nested behaviour
    receive() external payable {
        // attempt reentrancy; ignore failure
        try target.Put{value: 0}(block.timestamp + 1) {
            // no-op
        } catch {
            // if reentrant call reverts, bubble no further
        }
        // then revert to simulate a failing callee during some path
        revert("attacker revert");
    }
}

// Minimal Reverter helper (not used directly in this test but kept allowed per template)
contract Reverter { fallback() external payable { revert(); } }

