contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz: amount and a boolean to choose whether caller is a contract forwarder or an EOA
    function testFuzz_property(uint256 amount, bool useForwarder) public {
        // keep amount in a practical range and non-zero to allow observable deposit
        amount = bound(amount, 1 wei, 1 ether);

        address caller;
        Forwarder f;
        if (useForwarder) {
            // deploy a forwarding contract that will call c.Put on behalf of an externally owned test address
            f = new Forwarder();
            caller = address(f);
            // fund the forwarder so it can call Put with value
            vm.deal(caller, amount);
            // have the forwarder call c.Put{value: amount}(0)
            f.callPut{value: amount}(address(c));
        } else {
            // use an EOA (this) to call Put
            caller = address(this);
            vm.deal(caller, amount);
            vm.prank(caller);
            c.Put{value: amount}(0);
        }

        // The general rule: after Put by caller, Acc[caller].balance >= amount (the deposit is recorded)
        // This holds for the reference implementation for all inputs; the mutant that removed updating acc.balance
        // can leave Acc[caller].balance == 0 for some inputs (notably when a contract caller forwards funds),
        // so the assertion below will fail on the mutant for some fuzzed inputs.
        (uint bal,) = (c.Acc(caller)).balance; // try to access structure? cannot; instead use autogenerated getter
        // The mapping Acc is public and its getter signature is Acc(address) returns (uint unlockTime, uint balance)
        (uint unlockTime, uint recordedBalance) = c.Acc(caller);
        assertTrue(recordedBalance >= amount);
    }
}

