    constructor(C _c) { c = _c; }
    function run(uint deposit, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= deposit);
        // fund the contract and set unlock time so that Collect's conditions can be met
        // deposit into c from this contract
        c.Put{value: deposit}(unlockTime);

        // Now try Collect and observe whether it reverts
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }

        // Rule: If we attempted to collect an amount that was no more than what we deposited
        // (so collectAmount <= deposit) then in the original contract Collect will not revert
        // because it only sends Ether after checking balance and only updates balance on success.
        // The test asserts that for collectAmount <= deposit the call does not revert.
        assert(!(collectAmount <= deposit) || reverted == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will try to call Collect for a caller that should meet the conditions:
    // - caller has previously deposited at least MinSum and has unlockTime in the past
    // To avoid depending on internal storage reads, we require that this test
    // function is invoked with an ETH value that will be used to fund the contract
    // and then we make Collect from this contract (so msg.sender is this contract).

    // The test calls Collect once and asserts that for valid parameters the call does NOT revert.
    function run(uint depositAmount, uint collectAmount, uint unlockTime) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // Precondition: depositAmount >= MinSum and depositAmount >= collectAmount
        // We cannot call c.MinSum() in require? It's allowed (public). Use it.
        require(depositAmount >= c.MinSum(), "deposit must meet MinSum");
        require(depositAmount >= collectAmount, "deposit must cover collect");
        // Fund the contract by calling Put from this test contract, setting unlockTime in past so Collect is allowed
        // Use fallback Put via payable call to Put with unlockTime in the past (0) or provided unlockTime but ensure block.timestamp>unlockTime
        // Choose unlockTime = 0 to ensure block.timestamp>unlockTime
        c.Put{value: depositAmount}(0);
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: For a caller that previously deposited at least MinSum and at least collectAmount and whose unlockTime is passed, Collect should NOT revert in the original.
        // We express that by asserting reverted == false (i.e., call must succeed) under the preconditions we enforced.
        assert(reverted == false);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: amount to put, unlockTime set to past so that Collect is allowed, and amount to collect
    function run(uint putAmount, uint unlockDelta, uint collectAmount) public payable {
        // We will fund this test contract so it can send putAmount
        require(address(this).balance >= putAmount);
        // Ensure unlock time is in the past relative to block.timestamp so Collect's time check passes
        // unlockDelta is expected to be 0 or small; compute an unlockTime <= block.timestamp
        uint unlockTime = block.timestamp - unlockDelta;
        // Make a Put to deposit funds into c for address(this)
        c.Put{value: putAmount}(unlockTime);
        // Preconditions for the rule: recorded balance must be >= MinSum and >= collectAmount
        // We can only observe MinSum via the public getter, so read it first (view call allowed inside require)
        uint minSum = c.MinSum();
        require(putAmount >= minSum && putAmount >= collectAmount && collectAmount > 0);
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Rule: under these preconditions, original C never reverts. We express that as reverted == false.
        assert(reverted == false);
    }
    receive() external payable { }
}
